namespace sv_67d788b0ec1e44e0a48e5e85af30385b.Models;

// Domain records (as specified by the user)
public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

// Mutable form models for two-way binding
public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";

    public PersonalInfo ToRecord() => new(FullName, Email, Phone, Address);
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";

    public WorkEntry ToRecord() => new(Company, Title, StartDate ?? DateTime.Today, IsCurrent ? null : EndDate, Description);
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";

    public Reference ToRecord() => new(Name, Relationship, Email, Phone);
}

@* Step progress indicator bar *@

<nav aria-label="Application progress">
    <ol class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var css = step == CurrentStep ? "step active"
                    : CompletedSteps.Contains(step) ? "step completed"
                    : "step";

            <li class="@css"
                role="listitem"
                aria-current="@(step == CurrentStep ? "step" : null)">
                @if (CompletedSteps.Contains(step) && step != CurrentStep)
                {
                    <button class="step-btn" @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-circle">&#10003;</span>
                        <span class="step-label">@StepNames[i]</span>
                    </button>
                }
                else
                {
                    <span class="step-circle">@step</span>
                    <span class="step-label">@StepNames[i]</span>
                }
            </li>
        }
    </ol>
</nav>

@code {
    private static readonly string[] StepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

.step-indicator {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem 0;
    counter-reset: step;
    justify-content: space-between;
}

.step {
    flex: 1;
    text-align: center;
    position: relative;
    opacity: 0.4;
}

.step.active {
    opacity: 1;
    font-weight: 600;
}

.step.completed {
    opacity: 1;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #dee2e6;
    color: #495057;
    font-weight: 600;
    margin-bottom: 0.4rem;
}

.step.active .step-circle {
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    background: #198754;
    color: #fff;
}

.step-label {
    display: block;
    font-size: 0.85rem;
}

.step-btn {
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    color: inherit;
    font: inherit;
}

.step-btn:hover .step-circle {
    filter: brightness(0.85);
}

.step-btn:hover .step-label {
    text-decoration: underline;
}

/* Connector lines between steps */
.step + .step::before {
    content: '';
    position: absolute;
    top: 18px;
    left: -50%;
    right: 50%;
    height: 2px;
    background: #dee2e6;
    z-index: -1;
}

.step.active + .step::before,
.step.completed + .step::before {
    background: #198754;
}

@using sv_67d788b0ec1e44e0a48e5e85af30385b.Models

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h6 class="card-title mb-0">Reference @Index</h6>
            @if (CanRemove)
            {
                <button type="button" class="btn btn-sm btn-outline-danger" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Name</label>
                <input class="form-control" @bind="Ref.Name" @bind:event="oninput" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Relationship</label>
                <input class="form-control" @bind="Ref.Relationship" @bind:event="oninput" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="Ref.Email" @bind:event="oninput" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone</label>
                <input type="tel" class="form-control" @bind="Ref.Phone" @bind:event="oninput" />
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public ReferenceModel Ref { get; set; } = default!;
    [Parameter] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
}

