toolArgs.file_text:
.step-indicator {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0 0 2rem 0;
    counter-reset: step;
    justify-content: space-between;
}

.step {
    flex: 1;
    text-align: center;
    position: relative;
    opacity: 0.4;
}

.step.active {
    opacity: 1;
    font-weight: 600;
}

.step.completed {
    opacity: 1;
}

.step-circle {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #dee2e6;
    color: #495057;
    font-weight: 600;
    margin-bottom: 0.4rem;
}

.step.active .step-circle {
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-circle {
    background: #198754;
    color: #fff;
}

.step-label {
    display: block;
    font-size: 0.85rem;
}

.step-btn {
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    color: inherit;
    font: inherit;
}

.step-btn:hover .step-circle {
    filter: brightness(0.85);
}

.step-btn:hover .step-label {
    text-decoration: underline;
}

/* Connector lines between steps */
.step + .step::before {
    content: '';
    position: absolute;
    top: 18px;
    left: -50%;
    right: 50%;
    height: 2px;
    background: #dee2e6;
    z-index: -1;
}

.step.active + .step::before,
.step.completed + .step::before {
    background: #198754;
}

