arguments.file_text:
@using sv_67d788b0ec1e44e0a48e5e85af30385b.Models

<h4 class="mb-3">Personal Information</h4>

<div class="row g-3">
    <div class="col-md-6">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input class="form-control @(Errors.ContainsKey("FullName") ? "is-invalid" : "")"
               @bind="Model.FullName" @bind:event="oninput" />
        @if (Errors.TryGetValue("FullName", out var nameErr))
        {
            <div class="invalid-feedback">@nameErr</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email"
               class="form-control @(Errors.ContainsKey("Email") ? "is-invalid" : "")"
               @bind="Model.Email" @bind:event="oninput" />
        @if (Errors.TryGetValue("Email", out var emailErr))
        {
            <div class="invalid-feedback">@emailErr</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel"
               class="form-control @(Errors.ContainsKey("Phone") ? "is-invalid" : "")"
               @bind="Model.Phone" @bind:event="oninput" />
        @if (Errors.TryGetValue("Phone", out var phoneErr))
        {
            <div class="invalid-feedback">@phoneErr</div>
        }
    </div>
    <div class="col-md-6">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <input class="form-control @(Errors.ContainsKey("Address") ? "is-invalid" : "")"
               @bind="Model.Address" @bind:event="oninput" />
        @if (Errors.TryGetValue("Address", out var addrErr))
        {
            <div class="invalid-feedback">@addrErr</div>
        }
    </div>
</div>

@if (IsValidating)
{
    <div class="mt-3 text-muted"><span class="spinner-border spinner-border-sm"></span> Validating email…</div>
}

<div class="mt-4 d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">Next &rarr;</button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    [Inject] private IApplicationService AppService { get; set; } = default!;

    private Dictionary<string, string> Errors { get; set; } = new();
    private bool IsValidating { get; set; }

    private async Task HandleNext()
    {
        Errors.Clear();

        if (string.IsNullOrWhiteSpace(Model.FullName))
            Errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Model.Email))
            Errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Model.Phone))
            Errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Model.Address))
            Errors["Address"] = "Address is required.";

        if (Errors.Count > 0) return;

        IsValidating = true;
        try
        {
            var emailValid = await AppService.ValidateEmailAsync(Model.Email);
            if (!emailValid)
            {
                Errors["Email"] = "This email address is not valid.";
                return;
            }
        }
        finally
        {
            IsValidating = false;
        }

        await OnNext.InvokeAsync();
    }
}

@using sv_67d788b0ec1e44e0a48e5e85af30385b.Models

<h4 class="mb-3">Work History</h4>

@for (int i = 0; i < Entries.Count; i++)
{
    var idx = i;
    <WorkEntryEditor Entry="Entries[idx]"
                     Index="idx + 1"
                     CanRemove="Entries.Count > 1"
                     OnRemove="() => RemoveEntry(idx)" />
}

<button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
    + Add Another Position
</button>

@if (!string.IsNullOrEmpty(Error))
{
    <div class="alert alert-danger">@Error</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&larr; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &rarr;</button>
</div>

@code {
    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = [];
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? Error;

    private void AddEntry() => Entries.Add(new WorkEntryModel());

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        Error = null;
        foreach (var e in Entries)
        {
            if (string.IsNullOrWhiteSpace(e.Company) || string.IsNullOrWhiteSpace(e.Title) || e.StartDate is null)
            {
                Error = "Each position requires at least a company name, job title, and start date.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

@using sv_67d788b0ec1e44e0a48e5e85af30385b.Models

<h4 class="mb-3">References</h4>

@for (int i = 0; i < References.Count; i++)
{
    var idx = i;
    <ReferenceEditor Ref="References[idx]"
                     Index="idx + 1"
                     CanRemove="References.Count > 2"
                     OnRemove="() => RemoveReference(idx)" />
}

@if (References.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddReference">
        + Add Reference
    </button>
}

@if (!string.IsNullOrEmpty(Error))
{
    <div class="alert alert-danger">@Error</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&larr; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &rarr;</button>
</div>

@code {
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? Error;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
