{"file_text": "@page "/apply"
@rendermode InteractiveServer
@using sv_67d788b0ec1e44e0a48e5e85af30385b.Models

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (_submitted)
    {
        <div class="alert alert-success text-center py-5">
            <h3 class="mb-3">&#10003; Application Submitted!</h3>
            <p class="lead">Your application has been received.</p>
            <p>Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 1:
                <PersonalInfoStep Model="_personalInfo" OnNext="CompleteAndAdvance" />
                break;
            case 2:
                <WorkHistoryStep Entries="_workEntries" OnNext="CompleteAndAdvance" OnBack="GoBack" />
                break;
            case 3:
                <ReferencesStep References="_references" OnNext="CompleteAndAdvance" OnBack="GoBack" />
                break;
            case 4:
                <CoverLetterStep @bind-CoverLetter="_coverLetter" OnNext="CompleteAndAdvance" OnBack="GoBack" />
                break;
            case 5:
                <ReviewStep Personal="_personalInfo"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="_coverLetter"
                            IsSubmitting="_isSubmitting"
                            SubmitError="_submitError"
                            OnBack="GoBack"
                            OnSubmit="SubmitApplication"
                            OnEditSection="GoToStep" />
                break;
        }
    }
</div>

@code {
    [Inject] private IApplicationService AppService { get; set; } = default!;

    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = [];
    private bool _submitted;
    private int? _applicationId;
    private bool _isSubmitting;
    private string? _submitError;

    // Form state
    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new WorkEntryModel()];
    private readonly List<ReferenceModel> _references = [new ReferenceModel(), new ReferenceModel()];
    private string _coverLetter = "";

    private void CompleteAndAdvance()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void GoBack() => _currentStep--;

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
            _currentStep = step;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _submitError = null;

        try
        {
            var application = new JobApplication(
                _personalInfo.ToRecord(),
                new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
                _references.Select(r => r.ToRecord()).ToList(),
                _coverLetter
            );

            _applicationId = await AppService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}
", "path": "/tmp/sv-67d788b0ec1e44e0a48e5e85af30385b/Components/Pages/Apply/Apply.razor"}

