@using sv_67d788b0ec1e44e0a48e5e85af30385b.Models

<h4 class="mb-3">Review Your Application</h4>

@* Personal Info *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Personal Information</strong>
        <button class="btn btn-sm btn-link" @onclick='() => OnEditSection.InvokeAsync(1)'>Edit</button>
    </div>
    <div class="card-body">
        <dl class="row mb-0">
            <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@Personal.FullName</dd>
            <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@Personal.Email</dd>
            <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@Personal.Phone</dd>
            <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@Personal.Address</dd>
        </dl>
    </div>
</div>

@* Work History *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Work History</strong>
        <button class="btn btn-sm btn-link" @onclick='() => OnEditSection.InvokeAsync(2)'>Edit</button>
    </div>
    <div class="card-body">
        @foreach (var entry in WorkEntries)
        {
            <div class="mb-3">
                <h6>@entry.Title at @entry.Company</h6>
                <p class="text-muted mb-1">
                    @entry.StartDate?.ToString("MMM yyyy") &ndash;
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                </p>
                <p class="mb-0">@entry.Description</p>
            </div>
        }
    </div>
</div>

@* References *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>References</strong>
        <button class="btn btn-sm btn-link" @onclick='() => OnEditSection.InvokeAsync(3)'>Edit</button>
    </div>
    <div class="card-body">
        @foreach (var r in References)
        {
            <div class="mb-2">
                <strong>@r.Name</strong> — @r.Relationship<br />
                <span class="text-muted">@r.Email &middot; @r.Phone</span>
            </div>
        }
    </div>
</div>

@* Cover Letter *@
<div class="card mb-3">
    <div class="card-header d-flex justify-content-between align-items-center">
        <strong>Cover Letter</strong>
        <button class="btn btn-sm btn-link" @onclick='() => OnEditSection.InvokeAsync(4)'>Edit</button>
    </div>
    <div class="card-body">
        <p style="white-space: pre-wrap;">@CoverLetter</p>
    </div>
</div>

@if (!string.IsNullOrEmpty(SubmitError))
{
    <div class="alert alert-danger">@SubmitError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&larr; Back</button>
    <button class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
        @if (IsSubmitting)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Submit Application
    </button>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Personal { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = [];
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = [];
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = "";
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public string? SubmitError { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback<int> OnEditSection { get; set; }
}

@page "/apply"
@rendermode InteractiveServer
@using sv_67d788b0ec1e44e0a48e5e85af30385b.Models

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    @if (_submitted)
    {
        <div class="alert alert-success text-center py-5">
            <h3 class="mb-3">&#10003; Application Submitted!</h3>
            <p class="lead">Your application has been received.</p>
            <p>Application ID: <strong>@_applicationId</strong></p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        @switch (_currentStep)
        {
            case 1:
                <PersonalInfoStep Model="_personalInfo" OnNext="CompleteAndAdvance" />
                break;
            case 2:
                <WorkHistoryStep Entries="_workEntries" OnNext="CompleteAndAdvance" OnBack="GoBack" />
                break;
            case 3:
                <ReferencesStep References="_references" OnNext="CompleteAndAdvance" OnBack="GoBack" />
                break;
            case 4:
                <CoverLetterStep @bind-CoverLetter="_coverLetter" OnNext="CompleteAndAdvance" OnBack="GoBack" />
                break;
            case 5:
                <ReviewStep Personal="_personalInfo"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="_coverLetter"
                            IsSubmitting="_isSubmitting"
                            SubmitError="_submitError"
                            OnBack="GoBack"
                            OnSubmit="SubmitApplication"
                            OnEditSection="GoToStep" />
                break;
        }
    }
</div>

@code {
    [Inject] private IApplicationService AppService { get; set; } = default!;

    private int _currentStep = 1;
    private readonly HashSet<int> _completedSteps = [];
    private bool _submitted;
    private int? _applicationId;
    private bool _isSubmitting;
    private string? _submitError;

    // Form state
    private readonly PersonalInfoModel _personalInfo = new();
    private readonly List<WorkEntryModel> _workEntries = [new WorkEntryModel()];
    private readonly List<ReferenceModel> _references = [new ReferenceModel(), new ReferenceModel()];
    private string _coverLetter = "";

    private void CompleteAndAdvance()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void GoBack() => _currentStep--;

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
            _currentStep = step;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _submitError = null;

        try
        {
            var application = new JobApplication(
                _personalInfo.ToRecord(),
                new WorkHistory(_workEntries.Select(e => e.ToRecord()).ToList()),
                _references.Select(r => r.ToRecord()).ToList(),
                _coverLetter
            );

            _applicationId = await AppService.SubmitApplicationAsync(application);
            _submitted = true;
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

